/**
 * The wasm-bindgen output (`wasm/label_anything.js`, `--target web`), generated by
 * `npm run build:wasm` from `rust/crates/la-wasm`. Its exports are typed here instead of
 * by a generated `.d.ts`, so the TypeScript build does not depend on the Rust build.
 */
// @ts-ignore -- generated file, typed by `RawGlue` below
import * as generated from "../wasm/label_anything.js";

/** What `init` accepts: a URL or path to fetch, a fetch `Response`, the bytes or a compiled module. */
export type InitInput = RequestInfo | URL | Response | BufferSource | WebAssembly.Module;

/** The raw exports of `label-anything-wasm` (contract: `rust/crates/la-wasm/src/lib.rs`). */
export interface RawGlue {
  default(options?: { module_or_path?: InitInput | Promise<InitInput> }): Promise<unknown>;
  initSync(options: { module: BufferSource | WebAssembly.Module }): unknown;
  /** Result JSON (an object) or the errors of an invalid problem (a JSON array). */
  place(problemJson: string, options: unknown): string;
  validate(problemJson: string): string;
  /** Debug SVG, or the errors (a JSON array) when a JSON text is invalid. */
  renderSvg(problemJson: string, resultJson: string): string;
  version(): string;
  features(): string[];
  /** Raw calls executing; stays raised when a call ends in a panic or a trap. */
  callDepth(): number;
  /** Replace the instance by a fresh one (`--experimental-reset-state-function`). */
  __wbg_reset_state(): void;
  __testPanic(message: string): void;
  __testTrap(): void;
}

export const raw = generated as unknown as RawGlue;
